import{_ as t}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as n,o as a,af as i}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const f=JSON.parse('{"title":"Agent Plugins (Watchlist)","description":"Packaging Skills and MCP servers into one distributable plugin — Agent Plugins 1.0.0 is a package/conformance spec (manifest, fixed discovery locations, path containment) covering no permissions, sandbox, registry, or execution engine; an observation card, not yet canonical.","frontmatter":{"title":"Agent Plugins (Watchlist)","description":"Packaging Skills and MCP servers into one distributable plugin — Agent Plugins 1.0.0 is a package/conformance spec (manifest, fixed discovery locations, path containment) covering no permissions, sandbox, registry, or execution engine; an observation card, not yet canonical.","domain":"tech","tags":["tech","action","plugins","watchlist"],"navOrder":68,"topicId":"plugins","layer":"6","status":"watchlist","nodeType":"concept","owner":"learn-ai","externalOwners":[],"prerequisites":["skills","mcp"],"next":["protocol-map"],"specVersion":"Agent Plugins 1.0.0","lastVerified":"2026-09-01","bilingualParity":"exact","listed":true},"headers":[],"relativePath":"tech/06-agent-systems/plugins.md","filePath":"tech/06-agent-systems/plugins.md","lastUpdated":1791116096000}'),s={name:"tech/06-agent-systems/plugins.md"};function o(r,e,l,d,c,h){return a(),n("div",null,[...e[0]||(e[0]=[i(`<blockquote><p><strong>Group</strong>: Agent Systems | <strong>Previous group exit</strong>: you can wire model output into sessions and state | <strong>This group exit</strong>: you can judge when distribution needs Agent Plugins, and what it does and does not govern <strong>Prerequisites</strong>: <a href="./skills.html">Agent Skills</a>, <a href="./../07-interoperability/mcp.html">MCP</a> | <strong>Next</strong>: <a href="./../07-interoperability/">Protocol Map</a></p></blockquote><h2 id="_1-overview" tabindex="-1">1. Overview <a class="header-anchor" href="#_1-overview" aria-label="Permalink to &quot;1. Overview&quot;">​</a></h2><p><strong>Lead with the answer</strong>: when you need to hand someone <strong>a set</strong> of capabilities (several Skills plus several MCP server configurations) as <strong>one distributable unit</strong>, Agent Plugins 1.0.0 defines the format contract for that package: a root <code>plugin.json</code> manifest, fixed discovery locations (<code>skills/</code> and <code>mcp.json</code>), path-containment rules, and the <code>\${PLUGIN_ROOT}</code>/<code>\${PLUGIN_DATA}</code> variables. It is a <strong>package/conformance specification</strong> — it defines <em>what a package looks like and how clients validate and discover it</em>, and <strong>not</strong> an execution, permission, or distribution infrastructure. This page is a watchlist card: learn-ai does not yet depend on it in production.</p><h3 id="mental-model-one-plugin-package" tabindex="-1">Mental model: one plugin package <a class="header-anchor" href="#mental-model-one-plugin-package" aria-label="Permalink to &quot;Mental model: one plugin package&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>my-plugin/</span></span>
<span class="line"><span>├── plugin.json          # required: closed-schema manifest ($schema, name required)</span></span>
<span class="line"><span>├── skills/              # fixed location ①: one Skill per immediate subdirectory (each with SKILL.md)</span></span>
<span class="line"><span>│   └── summarize/</span></span>
<span class="line"><span>│       └── SKILL.md</span></span>
<span class="line"><span>├── mcp.json             # fixed location ②: MCP server connection config (stdio / streamable-http / sse)</span></span>
<span class="line"><span>├── com.example.client/  # client extension directory (reverse-domain namespace)</span></span>
<span class="line"><span>└── LICENSE</span></span></code></pre></div><p>Two-layer ownership: <strong>the Skill format is owned by the Agent Skills specification; Plugins only defines how skills are discovered inside a package</strong> (immediate subdirectories of <code>skills/</code>, no recursive deep search). MCP wire behavior is owned by the MCP specification; Plugins only defines the portable <code>mcp.json</code> configuration format.</p><h3 id="when-to-use-when-not-to" tabindex="-1">When to use / when not to <a class="header-anchor" href="#when-to-use-when-not-to" aria-label="Permalink to &quot;When to use / when not to&quot;">​</a></h3><ul><li>Use: distributing a &quot;skills + tool connections&quot; bundle to multiple clients; internal toolchains wanting a single install unit.</li><li>Do not use: <ul><li>a single skill — use <a href="./skills.html">Skills</a> directly, no package needed;</li><li>tool connectivity alone — configure an MCP server directly;</li><li>permissions/sandbox/marketplace review — the Plugins spec provides none of these (see below).</li></ul></li></ul><h3 id="decision-table-choosing-a-distribution-shape" tabindex="-1">Decision table: choosing a distribution shape <a class="header-anchor" href="#decision-table-choosing-a-distribution-shape" aria-label="Permalink to &quot;Decision table: choosing a distribution shape&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Shape</th><th>Direction</th><th>Control</th><th>State</th><th>Trust domain</th><th>Lowest complexity</th></tr></thead><tbody><tr><td>Single Skill directory</td><td>knowledge injection</td><td>description triggering</td><td>static files</td><td>inside the host process</td><td>one folder</td></tr><tr><td>Agent Plugin package</td><td>combined distribution</td><td>manifest + fixed discovery locations</td><td>static directory + install state (PLUGIN_DATA)</td><td>inside the host process, no isolation across packages</td><td>plugin.json + components</td></tr><tr><td>Standalone MCP server</td><td>tool connectivity</td><td>protocol boundary + authorization</td><td>server process/session</td><td>across process boundary</td><td>one server</td></tr></tbody></table><h3 id="what-it-governs-does-not-per-the-verified-spec-text" tabindex="-1">What it governs / does not (per the verified spec text) <a class="header-anchor" href="#what-it-governs-does-not-per-the-verified-spec-text" aria-label="Permalink to &quot;What it governs / does not (per the verified spec text)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Governs (within v1.0.0)</th><th>Does not govern (explicitly out of spec)</th></tr></thead><tbody><tr><td>the closed <code>plugin.json</code> manifest (only 9 permitted top-level fields; unknown fields reported and ignored)</td><td><strong>Sandbox</strong>: the spec states &quot;these containment rules... do not sandbox a plugin subprocess or restrict paths supplied at runtime&quot;</td></tr><tr><td>fixed discovery locations: <code>skills/</code>, <code>mcp.json</code>; the manifest cannot inline component configuration</td><td><strong>Permission model</strong>: no permission fields, no approval flow; security is the client&#39;s own job</td></tr><tr><td>path containment: resolved paths must stay inside the plugin root; escapes hit the narrowest failure boundary</td><td><strong>Registry / marketplace</strong>: the design decisions deliberately choose directory-based packages (inspectable with <code>ls</code>/<code>git</code>), not registry-fetched bundles</td></tr><tr><td><code>\${PLUGIN_ROOT}</code> / <code>\${PLUGIN_DATA}</code> variables and the subprocess environment</td><td><strong>Execution engine</strong>: the client (plugin runtime) discovers, installs, loads, and executes</td></tr><tr><td>client conformance requirements and component-level non-fatal failure semantics</td><td>governance (defined separately in a Technical Charter)</td></tr></tbody></table><h3 id="historical-milestones" tabindex="-1">Historical milestones <a class="header-anchor" href="#historical-milestones" aria-label="Permalink to &quot;Historical milestones&quot;">​</a></h3><p>Agent Plugins 1.0.0, status Published (verified 2026-09-01). v1 defines exactly two component types: <strong>skills and MCP servers</strong>; commands, hooks, agents, rules, and LSP servers are explicitly listed in the spec&#39;s design decisions as &quot;too client-specific for v1&quot;.</p><h2 id="_2-usage" tabindex="-1">2. Usage <a class="header-anchor" href="#_2-usage" aria-label="Permalink to &quot;2. Usage&quot;">​</a></h2><p>A watchlist minimal hands-on: walk a manifest conformance check by hand (paper plus one zero-dependency JSON check, ≤15 minutes, no API key).</p><h3 id="step-1-write-a-minimal-valid-manifest" tabindex="-1">Step 1: write a minimal valid manifest <a class="header-anchor" href="#step-1-write-a-minimal-valid-manifest" aria-label="Permalink to &quot;Step 1: write a minimal valid manifest&quot;">​</a></h3><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;$schema&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://agent-plugins.org/schemas/1.0.0/plugin.schema.json&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;minimal-plugin&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><code>$schema</code> and <code>name</code> are the only required fields. <code>name</code> rules: 1-64 chars; only <code>a-z</code>, <code>0-9</code>, <code>-</code>, <code>.</code>; must start and end alphanumeric; no <code>--</code> and no <code>..</code>.</p><h3 id="step-2-zero-dependency-check-of-required-fields-and-naming-rules" tabindex="-1">Step 2: zero-dependency check of required fields and naming rules <a class="header-anchor" href="#step-2-zero-dependency-check-of-required-fields-and-naming-rules" aria-label="Permalink to &quot;Step 2: zero-dependency check of required fields and naming rules&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --input-type=module</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">import { readFileSync } from &quot;node:fs&quot;;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">const m = JSON.parse(readFileSync(&quot;plugin.json&quot;, &quot;utf-8&quot;));</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">const failures = [];</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">if (m.$schema !== &quot;https://agent-plugins.org/schemas/1.0.0/plugin.schema.json&quot;)</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  failures.push(&quot;$schema must be the 1.0.0 canonical identifier&quot;);</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">if (!/^[a-z0-9]([a-z0-9.-]*[a-z0-9])?$/.test(m.name ?? &quot;&quot;) || (m.name ?? &quot;&quot;).length &gt; 64</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    || /--|\\.\\./.test(m.name ?? &quot;&quot;))</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  failures.push(&quot;name violates 1.64/charset/no----or-.. rules&quot;);</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">const allowed = [&quot;$schema&quot;,&quot;name&quot;,&quot;version&quot;,&quot;description&quot;,&quot;author&quot;,&quot;homepage&quot;,&quot;repository&quot;,&quot;license&quot;,&quot;keywords&quot;,&quot;extensions&quot;];</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">for (const k of Object.keys(m)) if (!allowed.includes(k)) failures.push(\`unknown top-level field: \${k}\`);</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">console.log(failures.length ? \`FAIL \${failures.join(&quot;; &quot;)}\` : &quot;PASS minimal manifest conforms&quot;);</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">process.exit(failures.length ? 1 : 0);</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;</span></span></code></pre></div><p>Happy-path output: <code>PASS minimal manifest conforms</code> (exit 0).</p><h3 id="step-3-negative-case" tabindex="-1">Step 3: negative case <a class="header-anchor" href="#step-3-negative-case" aria-label="Permalink to &quot;Step 3: negative case&quot;">​</a></h3><p>Change <code>&quot;name&quot;</code> to <code>&quot;My-Plugin&quot;</code> (uppercase is invalid) and rerun: the output is <code>FAIL name violates 1.64/charset/no----or-.. rules</code>, exit 1.</p><h3 id="acceptance-and-cleanup" tabindex="-1">Acceptance and cleanup <a class="header-anchor" href="#acceptance-and-cleanup" aria-label="Permalink to &quot;Acceptance and cleanup&quot;">​</a></h3><p>Acceptance: the valid case exits 0 and the negative case exits 1. Cleanup: delete the temporary <code>plugin.json</code>. There is no host-onboarding step on this page — learn-ai consumes Agent Plugins in no production path, so integration experience is intentionally left blank.</p><h2 id="_3-principles" tabindex="-1">3. Principles <a class="header-anchor" href="#_3-principles" aria-label="Permalink to &quot;3. Principles&quot;">​</a></h2><h3 id="discovery-and-failure-boundaries" tabindex="-1">Discovery and failure boundaries <a class="header-anchor" href="#discovery-and-failure-boundaries" aria-label="Permalink to &quot;Discovery and failure boundaries&quot;">​</a></h3><ul><li>Components are discovered only from fixed locations: <code>skills/</code> (each <strong>immediate</strong> subdirectory containing a <code>SKILL.md</code> is one skill, no recursion) and <code>mcp.json</code> (the sole MCP configuration entry point; inlining into the manifest is forbidden).</li><li>Failures isolate at the narrowest boundary: one non-conforming skill → skip that skill; one invalid server entry → skip that server; a wholly invalid <code>mcp.json</code> → disable MCP for that plugin only; <strong>a manifest that violates the schema (bad required fields, etc.) → reject the whole package</strong>. A missing fixed location is not an error.</li><li>Path containment: package-relative paths in configuration must start with <code>./</code> and stay inside the plugin root after resolution (<code>../bin/server</code> is invalid); <code>command</code> is a single executable token, not a shell string.</li></ul><h3 id="spec-requirements-vs-local-measurement" tabindex="-1">Spec requirements vs local measurement <a class="header-anchor" href="#spec-requirements-vs-local-measurement" aria-label="Permalink to &quot;Spec requirements vs local measurement&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Spec requirement (Agent Plugins 1.0.0, verified 2026-09-01)</th><th>Local measurement (Section 2 fixture)</th></tr></thead><tbody><tr><td>required <code>$schema</code> (canonical identifier) and <code>name</code></td><td>check groups 1 and 2 of the script</td></tr><tr><td>name charset/length/start-end/repetition rules</td><td>the <code>My-Plugin</code> negative case is caught</td></tr><tr><td>closed top-level fields, unknown fields reported and ignored</td><td>the script lists unknown fields</td></tr><tr><td>v1 component types are skills + MCP servers only</td><td>the fixture does not cover component discovery (no production need; left as observation)</td></tr></tbody></table><h3 id="ownership-layering-with-skills-mcp" tabindex="-1">Ownership layering with Skills / MCP <a class="header-anchor" href="#ownership-layering-with-skills-mcp" aria-label="Permalink to &quot;Ownership layering with Skills / MCP&quot;">​</a></h3><p>One fact has one owner: Skill format → agentskills.io; MCP wire behavior → the MCP specification; <strong>Plugins owns only the &quot;package and discovery&quot; layer</strong>. Use this layering to decide where to look up a field.</p><h2 id="_4-development" tabindex="-1">4. Development <a class="header-anchor" href="#_4-development" aria-label="Permalink to &quot;4. Development&quot;">​</a></h2><p>Watchlist card: the runbooks below are a preview for &quot;if you decide to pilot&quot;, not verified experience from this repository.</p><h3 id="symptom-→-evidence-→-action-→-done-when" tabindex="-1">Symptom → Evidence → Action → Done when <a class="header-anchor" href="#symptom-→-evidence-→-action-→-done-when" aria-label="Permalink to &quot;Symptom → Evidence → Action → Done when&quot;">​</a></h3><p><strong>Symptom</strong>: a client rejects the whole plugin at load time. <strong>Evidence</strong>: the client&#39;s reported invalid field points at <code>plugin.json</code>; cross-checking shows a missing or mistyped required field (unknown top-level fields do not cause rejection — only other schema violations do). <strong>Action</strong>: fix the manifest itself; move unknown fields under the <code>extensions.&lt;reverse-domain&gt;</code> namespace. <strong>Done when</strong>: client logs show only component-level warnings (if any) and the package loads.</p><h3 id="symptom-→-evidence-→-action-→-done-when-1" tabindex="-1">Symptom → Evidence → Action → Done when <a class="header-anchor" href="#symptom-→-evidence-→-action-→-done-when-1" aria-label="Permalink to &quot;Symptom → Evidence → Action → Done when&quot;">​</a></h3><p><strong>Symptom</strong>: the plugin&#39;s MCP server will not start, but its skills work. <strong>Evidence</strong>: a server entry in <code>mcp.json</code> is invalid (e.g. <code>command</code> written as a shell string, <code>cwd</code> escaping the root) or its <code>$schema</code> version mismatches <code>plugin.json</code>. <strong>Action</strong>: repair the entry per §7.2 (<code>command</code> as one token, <code>./</code> relative paths, placeholders limited to <code>\${PLUGIN_ROOT}</code>/<code>\${PLUGIN_DATA}</code>); align versions. <strong>Done when</strong>: that server completes the MCP handshake; other components are unaffected.</p><h3 id="symptom-→-evidence-→-action-→-done-when-2" tabindex="-1">Symptom → Evidence → Action → Done when <a class="header-anchor" href="#symptom-→-evidence-→-action-→-done-when-2" aria-label="Permalink to &quot;Symptom → Evidence → Action → Done when&quot;">​</a></h3><p><strong>Symptom</strong>: data or dependencies vanish after upgrading the plugin. <strong>Evidence</strong>: writable state was placed inside the package directory — upgrades replace package contents wholesale. <strong>Action</strong>: move all writable state to <code>\${PLUGIN_DATA}</code> (the spec requires clients to preserve that directory across updates). <strong>Done when</strong>: caches, dependencies, and generated artifacts survive an upgrade.</p><h3 id="threshold-for-promotion-to-canonical" tabindex="-1">Threshold for promotion to canonical <a class="header-anchor" href="#threshold-for-promotion-to-canonical" aria-label="Permalink to &quot;Threshold for promotion to canonical&quot;">​</a></h3><p>This page promotes to canonical when either condition holds: learn-ai or a sibling site consumes Agent Plugins packages in a real path; or the ecosystem shows ≥2 independent clients with conformance claims. Until then, the de-facto package format remains whatever git repositories and product documents ship.</p><h2 id="_5-resource-library" tabindex="-1">5. Resource Library <a class="header-anchor" href="#_5-resource-library" aria-label="Permalink to &quot;5. Resource Library&quot;">​</a></h2><p>Four-level reading route:</p><ul><li><strong>Beginner</strong>: read this page; retell the &quot;governs / does not govern&quot; table.</li><li><strong>Builder</strong>: read spec §4–§7; assemble a minimal package by hand and run the Section 2 check.</li><li><strong>Operator</strong>: if piloting, wire the manifest check into the release pipeline; track schema version changes.</li><li><strong>Researcher</strong>: read the spec&#39;s Design Decisions and Conformance Checklist to understand &quot;why only two component types in v1&quot;.</li></ul><h3 id="resource-table" tabindex="-1">Resource table <a class="header-anchor" href="#resource-table" aria-label="Permalink to &quot;Resource table&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Name</th><th>Evidence level</th><th>Canonical URL</th><th>Use</th><th>Supported claim</th><th>Next</th></tr></thead><tbody><tr><td>Agent Plugins specification 1.0.0</td><td>L0 (official spec)</td><td><a href="https://agent-plugins.org/specification" target="_blank" rel="noreferrer">https://agent-plugins.org/specification</a></td><td>the single source of the package format contract</td><td>manifest schema, fixed locations, containment, no sandbox/registry (retrievedAt 2026-09-01)</td><td>compare with Sections 1 and 3</td></tr><tr><td>Official schema (1.0.0)</td><td>L0 (official artifact)</td><td><a href="https://agent-plugins.org/schemas/1.0.0/plugin.schema.json" target="_blank" rel="noreferrer">https://agent-plugins.org/schemas/1.0.0/plugin.schema.json</a></td><td>machine-readable validation</td><td>the <code>$schema</code> canonical identifier (retrievedAt 2026-09-01)</td><td>wire into JSON Schema validation</td></tr><tr><td>Agent Skills specification</td><td>L0 (official spec)</td><td><a href="https://agentskills.io/specification" target="_blank" rel="noreferrer">https://agentskills.io/specification</a></td><td>format owner of component ①</td><td>Skill format belongs to the Skills spec (retrievedAt 2026-09-01)</td><td><a href="./skills.html">Agent Skills</a></td></tr><tr><td>MCP specification</td><td>L0 (official spec)</td><td><a href="https://modelcontextprotocol.io/specification/latest" target="_blank" rel="noreferrer">https://modelcontextprotocol.io/specification/latest</a></td><td>behavior owner of component ②</td><td>MCP wire behavior belongs to the MCP spec (retrievedAt 2026-09-01)</td><td><a href="./../07-interoperability/mcp.html">MCP</a></td></tr></tbody></table><h3 id="active-falsification-and-open-questions" tabindex="-1">Active falsification and open questions <a class="header-anchor" href="#active-falsification-and-open-questions" aria-label="Permalink to &quot;Active falsification and open questions&quot;">​</a></h3><ul><li>Falsification entry: if a client&#39;s handling of the same <code>plugin.json</code> contradicts the &quot;spec vs local measurement&quot; table, trust the spec and that client&#39;s documentation, then revise this page.</li><li>Open: ecosystem adoption (no evidence, not stated); evolution of component types beyond v1 (commands/hooks/agents/rules/LSP); the fate of the <code>mcp.json</code> <code>sse</code> type as MCP deprecates HTTP+SSE.</li></ul><h3 id="learn-ai-stops-here-where-to-go-next" tabindex="-1">learn-ai stops here / where to go next <a class="header-anchor" href="#learn-ai-stops-here-where-to-go-next" aria-label="Permalink to &quot;learn-ai stops here / where to go next&quot;">​</a></h3><ul><li>Component formats and behavior: <a href="./skills.html">Agent Skills</a>, <a href="./../07-interoperability/mcp.html">MCP</a>.</li><li>The layer 4 protocol landscape: <a href="./../07-interoperability/">Protocol Map</a>.</li></ul>`,52)])])}const k=t(s,[["render",o]]);export{f as __pageData,k as default};
